import sys

def solve():
    # Read all tokens from standard input
    # This handles newlines and spaces automatically
    input_data = sys.stdin.read().split()

    if not input_data:
        return

    iterator = iter(input_data)

    try:
        # Read N and M
        N = int(next(iterator))
        M = int(next(iterator))

        # Read grid S (N rows)
        S = []
        for _ in range(N):
            S.append(next(iterator))

        # Read grid T (M rows)
        T = []
        for _ in range(M):
            T.append(next(iterator))

    except StopIteration:
        return

    # Iterate through all possible top-left positions (r, c) in S
    # r is row index (0 to N-M), c is column index (0 to N-M)
    # Output requires 1-based indexing, so we print r+1 and c+1
    for r in range(N - M + 1):
        for c in range(N - M + 1):
            # Check if the subgrid of S starting at (r, c) matches T
            match = True
            for i in range(M):
                for j in range(M):
                    if S[r + i][c + j] != T[i][j]:
                        match = False
                        break
                if not match:
                    break

            if match:
                print(f"{r + 1} {c + 1}")
                return

if __name__ == '__main__':
    solve()
