def solve():
    # Read the input string S
    s = sys.stdin.readline().strip()

    # Map for closing brackets to their corresponding opening brackets
    match_map = {')': '(', ']': '[', '>': '<'}

    # Stack to keep track of opening brackets
    stack = []

    for char in s:
        if char in match_map:
            # It's a closing bracket
            # Check if the stack is not empty and the top matches
            if stack and stack[-1] == match_map[char]:
                stack.pop()
            else:
                # If stack is empty or top doesn't match, it's invalid
                print("No")
                return
        else:
            # It's an opening bracket
            stack.append(char)

    # If stack is empty, all brackets were matched correctly
    if not stack:
        print("Yes")
    else:
        print("No")

