class Solution:
    def maxDifference(self, s: str) -> int:
        # Dictionary to store the frequency of each character
        freq = {}
        for char in s:
            freq[char] = freq.get(char, 0) + 1

        # Initialize variables to track max odd frequency and min even frequency
        max_odd_freq = 0
        min_even_freq = float('inf')

        # Iterate through the frequencies
        for count in freq.values():
            if count % 2 == 1:
                # If the frequency is odd, update the maximum odd frequency found so far
                if count > max_odd_freq:
                    max_odd_freq = count
            else:
                # If the frequency is even, update the minimum even frequency found so far
                if count < min_even_freq:
                    min_even_freq = count

        # Return the difference between the max odd frequency and min even frequency
        return max_odd_freq - min_even_freq
