from typing import List

class Solution:
    def numberOfComponents(self, properties: List[List[int]], k: int) -> int:
        n = len(properties)
        parent = list(range(n))

        def find(x):
            if parent[x] != x:
                parent[x] = find(parent[x])
            return parent[x]

        def union(x, y):
            rootX = find(x)
            rootY = find(y)
            if rootX != rootY:
                parent[rootX] = rootY

        for i in range(n):
            for j in range(i + 1, n):
                # Calculate intersection size
                # Using sets is efficient enough given constraints (values <= 100, m <= 100)
                set_i = set(properties[i])
                set_j = set(properties[j])
                intersection_size = len(set_i.intersection(set_j))

                if intersection_size >= k:
                    union(i, j)

        # Count the number of unique roots (connected components)
        components = 0
        for i in range(n):
            if parent[i] == i:
                components += 1

        return components
